insert into jj_collect.catalog(id,data) values('nu-355','{"id": "nu-355", "number": 355, "name_es": "El dragón de cinta y luz", "name_en": "The Dragon of Ribbon and Light", "character": "duo", "theme": "fantasia", "tags": ["kimetsu-no-yaiba", "gyutaro-daki"], "rarity": 2, "sell": 80, "scrap": 12, "craft": 70, "dedication_es": "Junté nuestras dos versiones para imaginar algo que no existiría igual por separado.", "dedication_en": "I brought our two versions together to imagine something that would not be the same apart.", "art": 24, "collection": "duodecimo-universo"}'::jsonb) on conflict(id) do nothing;
