insert into jj_collect.catalog(id,data) values('nu-357','{"id": "nu-357", "number": 357, "name_es": "Un eclipse en nuestro universo", "name_en": "An Eclipse in Our Universe", "character": "duo", "theme": "fantasia", "tags": ["kimetsu-no-yaiba", "gyutaro-daki"], "rarity": 3, "sell": 220, "scrap": 35, "craft": 200, "dedication_es": "Este cielo imposible guarda la ilusión de que todavía tenemos nuevas cosas por descubrir.", "dedication_en": "This impossible sky holds the hope that we still have new things to discover.", "art": 26, "collection": "duodecimo-universo"}'::jsonb) on conflict(id) do nothing;
